#include <algorithm>
#include <cmath>
#include <fstream>
#include <iostream>
#include <numeric>
#include <random>
#include <string>
#include <vector>
using namespace std;string enc(const string&p,const vector<int>&k){string o;for(int col:k)for(int i=col;i<(int)p.size();i+=k.size())o+=p[i];return o;}string dec(const string&s,const vector<int>&k){string o(s.size(),' ');int at=0;for(int col:k)for(int i=col;i<(int)s.size();i+=k.size())o[i]=s[at++];return o;}
vector<int>hung(const vector<vector<int>>&a){int n=a.size();vector<int>u(n+1),v(n+1),p(n+1),way(n+1);for(int i=1;i<=n;i++){p[0]=i;int j0=0;vector<int>mv(n+1,99999);vector<bool>used(n+1);do{used[j0]=true;int i0=p[j0],d=99999,j1=0;for(int j=1;j<=n;j++)if(!used[j]){int cur=-a[i0-1][j-1]-u[i0]-v[j];if(cur<mv[j])mv[j]=cur,way[j]=j0;if(mv[j]<d)d=mv[j],j1=j;}for(int j=0;j<=n;j++)if(used[j])u[p[j]]+=d,v[j]-=d;else mv[j]-=d;j0=j1;}while(p[j0]);do{int j1=way[j0];p[j0]=p[j1];j0=j1;}while(j0);}vector<int>x(n);for(int j=1;j<=n;j++)x[j-1]=p[j]-1;return x;}
vector<int>fit(const string&a,const string&b,const vector<int>&pattern,int w,const int*freq,int mode){int n=50,q=n/w,r=n%w,at=0;vector<int>starts(w),key(w);for(int j=0;j<w;j++){starts[j]=at;at+=q+pattern[j];}for(int lo:{1,0}){vector<int>cols,ranks;for(int col=0;col<w;col++)if((col<r)==lo)cols.push_back(col);for(int rank=0;rank<w;rank++)if(pattern[rank]==lo)ranks.push_back(rank);int z=cols.size();vector<vector<int>>cost(z,vector<int>(z));for(int i=0;i<z;i++)for(int j=0;j<z;j++)for(int row=0;row<q+lo;row++)if(a[cols[i]+w*row]==b[starts[ranks[j]]+row])cost[i][j]+=mode?50/freq[a[cols[i]+w*row]-'a']:4;auto as=hung(cost);for(int j=0;j<z;j++)key[ranks[j]]=cols[as[j]];}return key;}
struct State{vector<vector<int>>k,pat;int score,matches;};
int overlap(const string&a,const string&b,int n){vector<int>x,y;for(int i=0;i+n<=(int)a.size();i++){int u=0,v=0;for(int j=0;j<n;j++){u=u*26+a[i+j]-'a';v=v*26+b[i+j]-'a';}x.push_back(u);y.push_back(v);}sort(x.begin(),x.end());sort(y.begin(),y.end());int i=0,j=0,result=0;while(i<(int)x.size()&&j<(int)y.size()){if(x[i]==y[j])result++,i++,j++;else if(x[i]<y[j])i++;else j++;}return result;}
void evaluate(State&s,const string&p,const string&c,const int*freq,int mode){string x=c;for(int j=2;j>=0;j--)x=dec(x,s.k[j]);s.matches=0;for(int i=0;i<50;i++)s.matches+=x[i]==p[i];s.score=6*s.matches+2*overlap(x,p,2)+3*overlap(x,p,3);}
void sweep(State&s,const string&p,const string&c,const int*freq,int mode,int cycles){int ws[3]={21,19,20};evaluate(s,p,c,freq,mode);for(int round=0;round<cycles;round++){int before=s.score;for(int j=0;j<3;j++){string a=p,b=c;for(int h=0;h<j;h++)a=enc(a,s.k[h]);for(int h=2;h>j;h--)b=dec(b,s.k[h]);s.k[j]=fit(a,b,s.pat[j],ws[j],freq,mode);}evaluate(s,p,c,freq,mode);if(s.score==before)break;}}
int main(int argc,char**argv){ifstream f(argv[1]);string p,c;f>>p>>c;mt19937 rng(stoi(argv[2]));int restarts=stoi(argv[3]),steps=stoi(argv[4]);int freq[26]={};for(char x:p)freq[x-'a']++;int best=0;State saved;int ws[3]={21,19,20};for(int rr=0;rr<restarts;rr++){int mode=rr%2;State s;s.k.resize(3);s.pat.resize(3);for(int j=0;j<3;j++){s.k[j].resize(ws[j]);iota(s.k[j].begin(),s.k[j].end(),0);shuffle(s.k[j].begin(),s.k[j].end(),rng);s.pat[j].resize(ws[j]);for(int i=0;i<ws[j];i++)s.pat[j][i]=s.k[j][i]<50%ws[j];}sweep(s,p,c,freq,mode,3);for(int it=0;it<steps;it++){State next=s;int j=rng()%3,aa,bb;do{aa=rng()%ws[j];bb=rng()%ws[j];}while(next.pat[j][aa]==next.pat[j][bb]);if(rng()%2){swap(next.pat[j][aa],next.pat[j][bb]);sweep(next,p,c,freq,mode,3);}else{aa=rng()%ws[j];bb=rng()%ws[j];swap(next.k[j][aa],next.k[j][bb]);for(int h=0;h<ws[j];h++)next.pat[j][h]=next.k[j][h]<50%ws[j];evaluate(next,p,c,freq,mode);}double t=.1+24.*(1.-double(it%2000)/2000.);if(next.score>=s.score||log((rng()+1.)/4294967297.)<(next.score-s.score)/t)s=next;if(s.matches>best){best=s.matches;saved=s;cerr<<rr<<' '<<it<<' '<<best<<' '<<s.score<<'\n';}if(best==50)goto done;}}done:cout<<best<<'\n';for(auto k:saved.k){for(int x:k)cout<<x<<' ';cout<<'\n';}string out=p;for(auto k:saved.k)out=enc(out,k);cout<<out<<'\n';}
